import re, json, sys
from gen import *
LMUT='#5B6169'; LBD='#E4E6E9'; LS='#F5F6F7'; INK='#0D0F12'
CHRG='background-color:#3A4048;background-image:linear-gradient(135deg,#F2F4F6 0%,#8E959E 35%,#3A4048 60%,#C9CED6 100%);'
S=lambda n: CP(n) if not SAMPLE else SAMPLE.get(n,n)
SAMPLE=None
def bar(right): return f'<tr><td style="padding:16px 20px;background:{BG};border-bottom:1px solid {BD};font-family:{F};"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="text-align:left;"><img src="{LOGO}" width="30" height="30" alt="" style="display:inline-block;vertical-align:middle;border:0;"><span style="display:inline-block;vertical-align:middle;margin-left:8px;font-size:12px;font-weight:800;letter-spacing:.3em;color:#E6E8EB;">PEPTRIUM</span></td><td style="text-align:right;font-size:11px;color:{DIM};">{right}</td></tr></table></td></tr>'
def nohelp(f): return re.sub(r'<div style="font-size:15px;font-weight:700;color:#FFFFFF;margin-bottom:12px;">Fragen\?.*?</table><div style="height:28px;"></div>','',f,flags=re.S)
def cfoot(f): return f.replace('weil du den Peptrium-Newsletter abonniert hast.','weil du an der Kasse deine E-Mail-Adresse angegeben hast.')
def optout(): return row(f'<a href="{S("wk_abmelden")}" style="font-size:11px;color:{DIM};">Keine Warenkorb-Erinnerungen mehr</a>','0 22px 10px')
def mini(keys,c):
    cell=lambda k:f'<td width="50%" valign="top" style="width:50%;padding:5px;"><a href="{utm(P[k][3],c)}" style="display:block;text-decoration:none;background:{CARD};border:1px solid {BD};border-radius:14px;overflow:hidden;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="64" style="width:64px;line-height:0;"><img src="{U}sp-email/{P[k][2]}" width="64" height="64" alt="" style="display:block;border:0;"></td><td style="padding:8px 10px;text-align:left;font-family:{F};"><div style="font-size:13px;font-weight:800;color:#FFF;">{P[k][0]}</div><div style="font-size:11px;color:{MUT};">{P[k][1]}</div></td></tr></table></a></td>'
    return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>'+''.join(cell(k) for k in keys)+'</tr></table>'
def label(t,mb=8): return f'<div style="text-align:left;font-size:12px;font-weight:700;letter-spacing:.16em;color:{DIM};margin-bottom:{mb}px;">{t}</div>'
def wk_items():
    r=''
    for n in (1,2,3):
        bt=f'border-top:1px solid {BD};' if n>1 else ''
        r+=(f'<tr style="display:{S("wk_show_"+str(n))};"><td width="74" style="width:74px;padding:10px 0;{bt}"><img src="{S("wk_bild_"+str(n))}" width="62" height="62" alt="" style="display:block;width:62px;height:62px;border-radius:12px;border:0;background:#0D0F12;"></td>'
            f'<td style="padding:10px 6px;{bt}text-align:left;font-family:{F};"><div style="font-size:15px;font-weight:800;color:#FFF;">{S("wk_name_"+str(n))}</div><div style="font-size:12px;color:{MUT};margin-top:2px;">{S("wk_info_"+str(n))}</div></td>'
            f'<td align="right" style="padding:10px 0;{bt}font-size:15px;font-weight:800;color:#FFF;white-space:nowrap;font-family:{F};">{S("wk_preis_"+str(n))}</td></tr>')
    r+=f'<tr><td colspan="3" style="padding:2px 0 0;text-align:left;font-size:12px;color:{MUT};font-family:{F};">{S("wk_mehr")}</td></tr>'
    r+=f'<tr><td colspan="2" style="padding:12px 0 0;border-top:1px solid {BD};text-align:left;font-size:14px;color:{MUT};font-family:{F};">Summe</td><td align="right" style="padding:12px 0 0;border-top:1px solid {BD};font-size:18px;font-weight:800;color:#FFF;white-space:nowrap;font-family:{F};">{S("wk_summe")}</td></tr>'
    return f'<div style="border:1px solid {BD};background:{CARD};border-radius:18px;padding:8px 16px 16px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">{r}</table></div>'
def chips():
    c=''.join(f'<td align="center" style="padding:0 3px;"><div style="border:1px solid {BD};border-radius:999px;padding:8px 6px;font-size:11px;font-weight:700;color:#D9DDE2;white-space:nowrap;font-family:{F};">{t}</div></td>' for t in ['✓ HPLC-geprüft','✓ Diskret','✓ 2 Werktage'])
    return f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>{c}</tr></table>'
def qa(n,q,a): return f'<tr><td width="40" valign="top" style="width:40px;padding:14px 0;"><div style="width:30px;height:30px;line-height:30px;border-radius:50%;background:#FFFFFF;color:#0D0F12;font-weight:800;font-size:14px;text-align:center;font-family:{F};">{n}</div></td><td style="padding:14px 4px;text-align:left;font-family:{F};border-bottom:1px solid {BD};"><div style="font-size:15px;font-weight:800;color:#FFF;">{q}</div><div style="font-size:13px;line-height:1.55;color:{MUT};margin-top:4px;">{a}</div></td></tr>'
def thumbs(pre,ns=(1,2,3),show=True):
    return '<table role="presentation" cellpadding="0" cellspacing="0"><tr>'+''.join(f'<td width="56" style="width:56px;padding-right:8px;'+(f'display:{S(pre+"show_"+str(n))};' if show and n>1 else '')+f'"><img src="{S(pre+"bild_"+str(n))}" width="48" height="48" alt="" style="display:block;width:48px;height:48px;border-radius:10px;border:0;background:#0D0F12;"></td>' for n in ns)+'</tr></table>'

def build():
    M={}
    c='code-erinnerung'
    M['erinnerung']=body(bar('Erinnerung')
     +row(f'<div style="display:inline-block;{CHRG}border-radius:26px;padding:2px;"><div style="background:{CARD};border-radius:24px;padding:22px 34px;"><div style="font-size:84px;line-height:1;font-weight:800;color:#FFF;">{S("erinnerung_zahl")}</div><div style="font-size:12px;font-weight:700;letter-spacing:.24em;color:{MUT};margin-top:6px;">{S("erinnerung_label")}</div></div></div>'
       +f'<div style="font-size:30px;line-height:1.12;font-weight:800;color:#FFF;margin:24px 0 10px;">Dein Code<br>läuft bald ab.</div><div style="font-size:15px;line-height:1.55;color:{MUT};">Du hast ihn noch nicht eingelöst – danach verfällt er.</div>','34px 20px 24px')
     +row(f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border:1px solid {BD};border-radius:16px;overflow:hidden;"><tr><td width="32%" style="background:#FFFFFF;padding:16px 4px;text-align:center;font-family:{F};"><div style="font-size:26px;font-weight:800;color:#0D0F12;line-height:1;">{S("erinnerung_prozent")}</div></td><td style="background:{CARD};padding:14px 10px;text-align:center;border-left:2px dashed {IN};font-family:{F};"><div style="font-size:19px;font-weight:800;font-family:{MONO};color:#FFF;letter-spacing:.03em;word-break:break-all;">{S("erinnerung_code")}</div><div style="font-size:11px;color:{DIM};margin-top:3px;">gültig bis {S("erinnerung_bis")}</div></td></tr></table><div style="height:16px;"></div>'+btn('Code jetzt einlösen',utm('/alle-produkte/',c)),'0 20px 28px')
     +row(label('AM MEISTEN GEKAUFT')+mini(['reta','ghk'],c),'0 15px 30px')+nohelp(foot()))
    c='nachkauf'
    big=''.join(f'<td width="50%" valign="top" style="width:50%;padding:5px;"><div style="background:{CARD};border:1px solid {BD};border-radius:16px;overflow:hidden;text-align:left;"><img src="{S("nachkauf_bild_"+str(n))}" width="150" alt="" style="display:block;width:100%;height:auto;border:0;background:#0D0F12;"><div style="padding:12px;font-family:{F};"><div style="font-size:15px;font-weight:800;color:#FFF;">{S("nachkauf_name_"+str(n))}</div><div style="font-size:12px;color:{MUT};margin-top:2px;">{S("nachkauf_info_"+str(n))}</div></div></div></td>' for n in (1,2))
    M['nachkauf']=body(bar('Nachbestellen')
     +row(f'<div style="text-align:left;">{label("VOR 4 WOCHEN BESTELLT",0)}<div style="font-size:34px;line-height:1.08;font-weight:800;color:#FFF;letter-spacing:-.02em;margin:8px 0 18px;">Zeit für<br>Nachschub?</div></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>{big}</tr></table><div style="height:16px;"></div>'+btn('Alles mit einem Klick nachbestellen',S('nachkauf_link'))+f'<div style="font-size:12px;color:{DIM};margin-top:10px;">Landet direkt im Warenkorb – du kannst vor dem Bestellen noch alles ändern.</div>','30px 15px 28px')
     +abo(c)+nohelp(foot()))
    c='nachkauf-2'
    M['nachkauf2']=body(bar('Kurzer Hinweis')
     +row(f'<div style="text-align:left;border-left:3px solid #8E959E;padding:4px 0 4px 16px;font-family:{F};"><div style="font-size:24px;font-weight:800;color:#FFF;margin-bottom:12px;">Noch alles da?</div><div style="font-size:16px;line-height:1.65;color:#C9CDD2;">Hallo,<br><br>nur eine kurze Nachricht: Falls dein Vorrat langsam knapp wird – deine letzte Bestellung liegt mit einem Klick wieder im Warenkorb.<br><br>Und falls du Fragen hast, antworte einfach auf diese Mail.<br><br><span style="color:#FFF;font-weight:700;">Dein Peptrium-Team</span></div></div>','36px 24px 24px')
     +f'<tr><td style="padding:0 24px 32px;background:{IN};text-align:left;font-family:{F};">'+thumbs('nachkauf_',(1,2),False)+'<div style="height:16px;"></div>'+btn('Nachbestellen',S('nachkauf_link'))+'</td></tr>'+nohelp(foot()))
    c='rueckgewinnung'
    M['rueckgewinnung']=body(f'<tr><td style="padding:0;line-height:0;background:{BG};"><img src="{U}sp-email/nl-hero-pen.jpg" width="600" alt="" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr>'
     +row(f'<div style="font-size:12px;font-weight:700;letter-spacing:.2em;color:{MUT};">LANGE NICHT GESEHEN</div><div style="font-size:36px;line-height:1.05;font-weight:800;color:#FFF;margin:10px 0 12px;letter-spacing:-.02em;">Wir vermissen<br>dich.</div><div style="font-size:15px;line-height:1.55;color:{MUT};">Als kleines Dankeschön für dein Comeback:</div>','24px 20px 20px')
     +row(f'<div style="{CHRG}border-radius:20px;padding:2px;"><div style="background:#0B0D10;border-radius:18px;padding:26px 16px;"><div style="font-size:12px;font-weight:700;letter-spacing:.2em;color:{MUT};">DEIN COMEBACK-CODE</div><div style="font-size:60px;font-weight:800;color:#FFF;line-height:1.1;margin:6px 0;">{S("comeback_prozent")}</div><div style="font-size:21px;font-weight:800;font-family:{MONO};color:#D9DDE2;letter-spacing:.04em;word-break:break-all;">{S("comeback_code")}</div><div style="font-size:12px;color:{DIM};margin-top:8px;">nur 14 Tage gültig · bis {S("comeback_bis")}</div></div></div><div style="height:16px;"></div>'+btn('Jetzt einlösen',utm('/alle-produkte/',c)),'0 20px 30px')
     +row(label('GERADE BELIEBT',6)+f'<div style="text-align:left;font-size:20px;font-weight:800;color:#FFF;margin-bottom:12px;">Fertig gemischt oder klassisch</div>'+mini(['pen','reta'],c),'0 15px 30px')+nohelp(foot()))
    M['warenkorb1']=body(bar('Dein Warenkorb')
     +row(f'<div style="text-align:left;"><div style="font-size:34px;line-height:1.08;font-weight:800;color:#FFF;letter-spacing:-.02em;">Dein Warenkorb<br>wartet noch.</div><div style="font-size:15px;line-height:1.55;color:{MUT};margin:12px 0 20px;">Wir haben alles für dich gespeichert. Mit einem Klick geht es genau dort weiter, wo du aufgehört hast.</div></div>'+wk_items()+'<div style="height:16px;"></div>'+btn('Bestellung abschließen →',S('wk_link'))+'<div style="height:18px;"></div>'+chips(),'30px 20px 30px')
     +optout()+cfoot(foot()))
    M['warenkorb2']=body(bar('Kurze Frage')
     +row(f'<div style="text-align:left;"><div style="font-size:34px;line-height:1.08;font-weight:800;color:#FFF;letter-spacing:-.02em;">Noch Fragen<br><span style="color:#8E959E;">vor dem Bestellen?</span></div><div style="font-size:15px;line-height:1.55;color:{MUT};margin:12px 0 6px;">Viele zögern beim ersten Mal – das verstehen wir. Hier die häufigsten Fragen:</div></div>'
       +'<table role="presentation" width="100%" cellpadding="0" cellspacing="0">'+qa(1,'Wie bezahle ich?','Per Vorkasse (Überweisung) oder Krypto. Nach Zahlungseingang geht dein Paket raus.')+qa(2,'Wie schnell kommt es an?','In der Regel innerhalb von 2 Werktagen per DHL, ab 100 € versandkostenfrei.')+qa(3,'Wie wird verpackt?','Neutral und diskret, ohne Hinweis auf den Inhalt.')+'</table>','30px 20px 22px')
     +row(f'<div style="border:1px solid {BD};background:{CARD};border-radius:18px;padding:20px 16px;"><div style="font-size:17px;font-weight:800;color:#FFF;margin-bottom:4px;">Frag uns direkt</div><div style="font-size:13px;color:{MUT};margin-bottom:14px;">Wir antworten meist innerhalb weniger Stunden.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="50%" style="padding-right:5px;"><a href="mailto:info@peptrium.com" style="display:block;background:#FFFFFF;color:#0D0F12;text-decoration:none;font-weight:800;font-size:14px;padding:13px 6px;border-radius:12px;text-align:center;">✉️ E-Mail</a></td><td width="50%" style="padding-left:5px;"><a href="https://t.me/peptrium" style="display:block;background:#229ED9;color:#FFFFFF;text-decoration:none;font-weight:800;font-size:14px;padding:13px 6px;border-radius:12px;text-align:center;">Telegram</a></td></tr></table></div>','0 20px 26px')
     +f'<tr><td style="padding:0 20px 30px;background:{IN};text-align:left;font-family:{F};">'+label('DEIN WARENKORB · '+S('wk_summe'),10)+thumbs('wk_')+'<div style="height:16px;"></div>'+btn('Zum Warenkorb →',S('wk_link'))+'</td></tr>'
     +optout()+nohelp(cfoot(foot())))
    lrow=lambda inner,pad='26px 20px',bg='#FFFFFF':f'<tr><td style="padding:{pad};background:{bg};text-align:left;font-family:{F};color:{INK};">{inner}</td></tr>'
    def step(n,t,d,link,lt): return f'<tr><td width="44" valign="top" style="width:44px;padding:14px 0;"><div style="width:32px;height:32px;line-height:32px;border-radius:50%;background:{INK};color:#FFF;font-weight:800;font-size:14px;text-align:center;">{n}</div></td><td style="padding:14px 4px;border-bottom:1px solid {LBD};"><div style="font-size:16px;font-weight:800;color:{INK};">{t}</div><div style="font-size:13px;line-height:1.55;color:{LMUT};margin:3px 0 6px;">{d}</div><a href="{link}" style="font-size:13px;font-weight:700;color:{INK};">{lt} →</a></td></tr>'
    li=''.join(f'<td width="50%" valign="top" style="width:50%;padding:5px;'+(f'display:{S("nl_show_2")};' if n==2 else '')+f'"><div style="border:1px solid {LBD};border-radius:14px;overflow:hidden;background:#FFF;"><img src="{S("nl_bild_"+str(n))}" width="150" alt="" style="display:block;width:100%;height:auto;border:0;"><div style="padding:10px;"><div style="font-size:14px;font-weight:800;color:{INK};">{S("nl_name_"+str(n))}</div><div style="font-size:12px;color:{LMUT};">{S("nl_info_"+str(n))}</div></div></div></td>' for n in (1,2))
    c='nach-lieferung'
    M['nachlieferung']=('<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#E9EBED;"><tr><td align="center" style="padding:0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#FFFFFF;">'
     +bar('Bestellung #'+S('nl_nr'))
     +lrow(f'<div style="font-size:12px;font-weight:700;letter-spacing:.16em;color:{LMUT};">📦 ZUGESTELLT</div><div style="font-size:32px;line-height:1.1;font-weight:800;color:{INK};margin:8px 0 10px;letter-spacing:-.02em;">Ist alles gut<br>angekommen?</div><div style="font-size:15px;line-height:1.55;color:{LMUT};">Deine Bestellung sollte inzwischen bei dir sein. Damit deine Forschung gut startet, hier 3 kurze Punkte.</div>','30px 20px 10px')
     +lrow('<table role="presentation" width="100%" cellpadding="0" cellspacing="0">'+step(1,'Lieferung prüfen','Stimmt alles? Falls etwas fehlt oder beschädigt ist, melde dich – wir kümmern uns sofort.','mailto:info@peptrium.com','Problem melden')+step(2,'Richtig lagern','Lyophilisierte Peptide kühl und dunkel, gelöste im Kühlschrank.',utm('/lagerungs-guide/',c),'Lagerungs-Guide')+step(3,'Exakt rekonstituieren','Der Peptid-Rechner zeigt dir die passende Menge Bac Water.',utm('/peptid-rechner/',c),'Peptid-Rechner')+'</table>','6px 20px 24px')
     +lrow(f'<div style="font-size:12px;font-weight:700;letter-spacing:.16em;color:{LMUT};margin-bottom:8px;">DEINE BESTELLUNG</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>{li}</tr></table><div style="height:16px;"></div><a href="{S("nl_link")}" style="display:block;background:#FFF;color:{INK};border:1.5px solid {INK};text-align:center;text-decoration:none;font-weight:800;font-size:15px;padding:14px;border-radius:12px;">Erneut bestellen</a>','10px 15px 30px',LS)
     +foot().replace('weil du den Peptrium-Newsletter abonniert hast','weil du bei Peptrium bestellt hast')+'</table></td></tr></table>')
    return M
if __name__=='__main__':
    for k,v in build().items(): open('final_'+k+'.body','w').write(v)
    print('ok', [k for k in build()])
